export default function build({ THREE, kit, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const accent = '#ff7a33';

  // Key dimensions (meters)
  const BR = 0.19, y0 = 0.14, H = 0.18, yTop = y0 + H;
  const coneR = (t) => 0.042 + 0.118 * Math.pow(1 - t, 1.8);
  const FLOW_PHI = 1.75;

  const stand = kit.stand(0.23, { accent });
  root.add(stand);
  const B = stand.userData.top;

  const parts = [];
  let selected = null;
  let cut = true;
  const hl = new THREE.Color('#ffc94d');
  const DS = THREE.DoubleSide;

  // ---------- Panel ----------
  const panel = ui(`
    <style>${kit.theme({ accent })}</style>
    <div class="panel">
      <div class="bar"></div>
      <span class="eyebrow">INSIDE A VOLCANO</span>
      <span class="title" id="name">Stratovolcano</span>
      <span class="body" id="desc">Tap any part to learn its role in the volcano.</span>
      <div class="row">
        <button class="btn" id="cut"><span class="btn-text" id="cutText">Cutaway: on</span></button>
        <button class="btn2" id="reset"><span class="btn2-text">Reset</span></button>
      </div>
      <span class="small">Tap to highlight. Pinch to lift or turn a part.</span>
    </div>`, { width: 0.3, position: [0.4, 0.2, 0], rotationY: -0.15 });
  root.add(panel.object3D);

  // ---------- Helpers ----------
  const dedupe = (pts) => {
    const out = [];
    pts.forEach((p) => {
      const q = out[out.length - 1];
      if (!q || Math.abs(q[0] - p[0]) > 1e-6 || Math.abs(q[1] - p[1]) > 1e-6) out.push(p);
    });
    if (out.length > 1) {
      const a = out[0], b = out[out.length - 1];
      if (Math.abs(a[0] - b[0]) < 1e-6 && Math.abs(a[1] - b[1]) < 1e-6) out.pop();
    }
    return out;
  };

  // Flat cross-section face (plane z = 0) from a lathe profile
  function capGeo(profile, hollow, uv) {
    let shapes;
    if (hollow) {
      const p = dedupe(profile);
      shapes = [
        new THREE.Shape(p.map((q) => new THREE.Vector2(q[0], q[1]))),
        new THREE.Shape(p.map((q) => new THREE.Vector2(-q[0], q[1]))),
      ];
    } else {
      const mirrored = profile.slice().reverse().map((q) => [-q[0], q[1]]);
      const poly = dedupe(profile.concat(mirrored));
      shapes = [new THREE.Shape(poly.map((q) => new THREE.Vector2(q[0], q[1])))];
    }
    const g = new THREE.ShapeGeometry(shapes);
    if (uv) {
      const pos = g.attributes.position, t = g.attributes.uv;
      for (let i = 0; i < pos.count; i++) {
        t.setXY(i, (pos.getX(i) + uv.R) / (2 * uv.R), (pos.getY(i) - uv.y0) / uv.H);
      }
    }
    return g;
  }

  function lathePart(name, layers, z) {
    const g = new THREE.Group();
    g.name = name;
    g.userData.full = [];
    g.userData.half = [];
    g.userData.mats = [];
    layers.forEach((L) => {
      const pts = L.profile.map(([r, y]) => new THREE.Vector2(r, y));
      const full = new THREE.Mesh(new THREE.LatheGeometry(pts, 64), L.mat);
      const half = new THREE.Mesh(new THREE.LatheGeometry(pts, 40, Math.PI / 2, Math.PI), L.mat);
      const cap = new THREE.Mesh(capGeo(L.profile, L.hollow, L.uv), L.capMat || L.mat);
      cap.position.z = z || 0;
      g.add(full, half, cap);
      g.userData.full.push(full);
      g.userData.half.push(half, cap);
      [L.mat, L.capMat].forEach((m) => {
        if (m) m.side = DS;
        if (m && !g.userData.mats.includes(m)) g.userData.mats.push(m);
      });
    });
    return g;
  }

  // The pivot is given explicitly (pre-stand coordinates) so every part stays exactly in place.
  function finish(g, label, desc, center, opts) {
    const o = opts || {};
    root.add(g);
    const c = new THREE.Vector3(center[0], center[1], center[2]);
    g.children.forEach((ch) => ch.position.sub(c));
    (o.extras || []).forEach((e) => { e.position.sub(c); g.add(e); });
    g.position.set(c.x, c.y + B, c.z);
    g.userData.home = g.position.clone();
    g.userData.label = label;
    g.userData.desc = desc;
    g.userData.interior = !!o.interior;
    g.userData.lava = !!o.lava;
    g.userData.mats.forEach((m) => {
      m.userData.ec = m.emissive.clone();
      m.userData.ei = m.emissiveIntensity;
    });
    traits(g, { grab: true, onPress: () => select(g) });
    parts.push(g);
    return g;
  }

  function select(g) {
    selected = g;
    panel.set('name', { text: g.userData.label });
    panel.set('desc', { text: g.userData.desc });
  }

  function applyCut() {
    parts.forEach((p) => {
      p.userData.full.forEach((o) => { o.visible = !cut; });
      p.userData.half.forEach((o) => { o.visible = cut; });
      p.visible = cut || !p.userData.interior;
    });
    panel.set('cutText', { text: cut ? 'Cutaway: on' : 'Cutaway: off' });
  }

  const strata = (c1, c2, scale) => new THREE.MeshStandardMaterial({
    map: kit.texture('noise', { colors: [c1, c2], scale, warp: 0.4 }), roughness: 0.95, side: DS,
  });

  // ---------- Bedrock: five distinct strata ----------
  const defs = [
    [0, 0.04, '#2e2d33', '#4a4850'],
    [0.04, 0.075, '#6b665f', '#8a857b'],
    [0.075, 0.11, '#a5744a', '#c8955f'],
    [0.11, 0.13, '#4a3624', '#6b5236'],
    [0.13, y0, '#3f6b2c', '#62903c'],
  ];
  const bedrock = lathePart('Bedrock layers', defs.map(([a, b, c1, c2]) => ({
    profile: [[0, a], [BR, a], [BR, b], [0, b]],
    mat: strata(c1, c2, 7),
    uv: { R: BR, y0: a, H: b - a },
  })), 0);

  // Pine trees: trunk plus two tiers
  const trunkMat = kit.material('wood', { color: '#5a3d26' });
  const pineMat = kit.material('leaf', { color: '#2f5d34' });
  function trees(list) {
    const g = new THREE.Group();
    const at = (dy) => list.map(([x, z]) => [x, y0 + dy, z]);
    g.add(
      kit.instances(new THREE.CylinderGeometry(0.0022, 0.0032, 0.012, 8), trunkMat, at(0.006)),
      kit.instances(new THREE.ConeGeometry(0.0125, 0.026, 10), pineMat, at(0.025)),
      kit.instances(new THREE.ConeGeometry(0.009, 0.022, 10), pineMat, at(0.04)),
    );
    return g;
  }
  const backList = [], frontList = [];
  for (let i = 0; i < 11; i++) {
    const a = Math.PI / 2 + 0.2 + (i * (Math.PI - 0.4)) / 10;
    if (Math.abs(a - FLOW_PHI) < 0.35) continue;
    const r = 0.172 + (i % 2) * 0.008;
    backList.push([r * Math.sin(a), r * Math.cos(a)]);
  }
  for (let i = 0; i < 9; i++) {
    const a = -Math.PI / 2 + 0.2 + (i * (Math.PI - 0.4)) / 8;
    const r = 0.172 + (i % 2) * 0.008;
    frontList.push([r * Math.sin(a), r * Math.cos(a)]);
  }
  const backTrees = trees(backList), frontTrees = trees(frontList);
  bedrock.add(backTrees, frontTrees);
  bedrock.userData.full.push(frontTrees);
  finish(bedrock, 'Bedrock layers',
    'Layers of rock lie under the volcano, and the magma chamber is buried inside them.', [0, 0.07, 0]);

  // ---------- Outer cone ----------
  const coneMat = kit.material('rock', { color: '#6a5e55', wear: 0.5 });
  const coneCapMat = new THREE.MeshStandardMaterial({
    map: kit.texture('bands', { colors: ['#4b4039', '#7a6a58', '#3a332e', '#8a7a66', '#55483f'], count: 9, warp: 0.35 }),
    roughness: 0.9,
  });
  const coneProfile = [[0, y0], [coneR(0), y0]];
  for (let k = 1; k <= 16; k++) coneProfile.push([coneR(k / 16), y0 + H * (k / 16)]);
  coneProfile.push([0, yTop]);
  const cone = lathePart('Outer cone', [{
    profile: coneProfile, mat: coneMat, capMat: coneCapMat, uv: { R: coneR(0), y0, H },
  }], 0);

  // Gullies running down the flanks
  const gullyGeo = kit.roundedBox(0.009, 0.05, 0.004, 0.0015);
  const gullyMat = kit.material('rock', { color: '#2b2622', wear: 0.6 });
  const dummy = new THREE.Object3D();
  dummy.rotation.order = 'YXZ';
  function gullies(phis) {
    const mats = [];
    [[0.26, 1.4], [0.55, 1.1]].forEach(([t, len]) => {
      phis.forEach((ph, i) => {
        const tt = t + (i % 2) * 0.08;
        const r = coneR(tt) + 0.0012;
        const tilt = Math.atan2(coneR(tt - 0.05) - coneR(tt + 0.05), 0.1 * H);
        dummy.position.set(r * Math.sin(ph), y0 + H * tt, r * Math.cos(ph));
        dummy.rotation.set(-tilt, ph, 0);
        dummy.scale.set(1, len, 1);
        dummy.updateMatrix();
        mats.push(dummy.matrix.clone());
      });
    });
    const m = new THREE.InstancedMesh(gullyGeo, gullyMat, mats.length);
    mats.forEach((mx, i) => m.setMatrixAt(i, mx));
    m.frustumCulled = false;
    return m;
  }
  const bp = [], fp = [];
  for (let i = 0; i < 9; i++) {
    const a = Math.PI / 2 + 0.15 + (i * (Math.PI - 0.3)) / 8;
    if (Math.abs(a - FLOW_PHI) > 0.3) bp.push(a);
    fp.push(-Math.PI / 2 + 0.15 + (i * (Math.PI - 0.3)) / 8);
  }
  const bg = gullies(bp), fg = gullies(fp);
  cone.add(bg, fg);
  cone.userData.full.push(fg);
  finish(cone, 'Outer cone',
    'Layers of ash and hardened lava pile up around the vent to build the steep cone.', [0, y0 + H / 2, 0]);

  // ---------- Crater ----------
  const craterMat = kit.material('rock', { color: '#3f3833', wear: 0.6 });
  const crater = lathePart('Crater', [{
    hollow: true, mat: craterMat,
    profile: [[0.024, yTop - 0.006], [0.047, yTop - 0.006], [0.044, yTop + 0.004], [0.040, yTop + 0.012],
      [0.035, yTop + 0.011], [0.029, yTop + 0.003], [0.024, yTop - 0.002]],
  }], 0.002);
  finish(crater, 'Crater',
    'The bowl-shaped crater at the summit is where erupting material leaves the volcano.', [0, yTop, 0]);

  // ---------- Vent with glow and ash plume ----------
  const ventGlow = kit.glow('#ff7a2a', 0.1, { opacity: 0.6 });
  ventGlow.position.set(0, yTop + 0.012, 0);
  const smoke = kit.particles({ count: 26, box: [0.05, 0.1, 0.05], color: '#8d8780', size: 0.018 });
  smoke.position.set(0, yTop + 0.08, 0);
  const puffs = [];
  for (let i = 0; i < 4; i++) {
    const p = kit.glow('#7d776f', 0.05, { opacity: 0.3 });
    p.position.set(0, yTop + 0.03, 0);
    puffs.push(p);
  }
  const vent = lathePart('Vent', [{
    mat: kit.material('lava'),
    profile: [[0, yTop - 0.004], [0.022, yTop - 0.004], [0.019, yTop + 0.001], [0.012, yTop + 0.006], [0, yTop + 0.007]],
  }], 0.003);
  finish(vent, 'Vent',
    'The vent is the opening at the top of the conduit where magma, gas and ash exit.',
    [0, yTop, 0], { lava: true, extras: [ventGlow, smoke].concat(puffs) });
  puffs.forEach((p) => { p.userData.p0 = p.position.clone(); });

  // ---------- Central conduit ----------
  const conduit = lathePart('Central conduit', [{
    mat: kit.material('lava'),
    profile: [[0, 0.09], [0.022, 0.09], [0.014, 0.118], [0.014, yTop], [0, yTop]],
  }], 0.003);
  finish(conduit, 'Central conduit',
    'The conduit is the central pipe that carries magma up from the chamber to the vent.',
    [0, 0.12, 0], { lava: true, interior: true });

  // ---------- Magma chamber ----------
  const chamberProfile = [];
  for (let i = 0; i <= 24; i++) {
    const t = -Math.PI / 2 + (Math.PI * i) / 24;
    let r = 0.092 * Math.cos(t) * (1 + 0.07 * Math.sin(3 * t));
    if (i === 0 || i === 24) r = 0;
    chamberProfile.push([r, 0.055 + 0.045 * Math.sin(t)]);
  }
  const chamber = lathePart('Magma chamber', [{ profile: chamberProfile, mat: kit.material('lava') }], 0.002);
  finish(chamber, 'Magma chamber',
    'The magma chamber is a huge pocket of molten rock stored deep underground.',
    [0, 0.055, 0], { lava: true, interior: true });

  // ---------- Lava flow ----------
  const flowPts = [];
  for (let k = 0; k <= 9; k++) {
    const t = 0.97 - (k / 9) * 0.97;
    const phi = FLOW_PHI + 0.12 * Math.sin(k * 0.9);
    const r = coneR(t) + 0.004;
    flowPts.push([r * Math.sin(phi), y0 + H * t + 0.003, r * Math.cos(phi)]);
  }
  [0.174, 0.186].forEach((r) => flowPts.push([r * Math.sin(FLOW_PHI), y0 + 0.004, r * Math.cos(FLOW_PHI)]));
  const flowMat = kit.material('lava');
  flowMat.side = DS;
  const flow = new THREE.Group();
  flow.name = 'Lava flow';
  flow.userData.full = [];
  flow.userData.half = [];
  flow.userData.mats = [flowMat];
  flow.add(new THREE.Mesh(kit.tube(flowPts, 0.005), flowMat));
  flowPts.forEach((p, k) => {
    if (k % 2 === 1 || k > 9) {
      const b = new THREE.Mesh(new THREE.SphereGeometry(0.006 + 0.0009 * k, 14, 10), flowMat);
      b.scale.set(1, 0.45, 1.3);
      b.position.set(p[0], p[1], p[2]);
      flow.add(b);
    }
  });
  kit.merge(flow);
  const tip = flowPts[flowPts.length - 1];
  const tipGlow = kit.glow('#ff6a1f', 0.05, { opacity: 0.5 });
  tipGlow.position.set(tip[0], tip[1] + 0.005, tip[2]);
  const fc = flowPts.reduce((a, p) => [a[0] + p[0] / flowPts.length, a[1] + p[1] / flowPts.length, a[2] + p[2] / flowPts.length], [0, 0, 0]);
  finish(flow, 'Lava flow',
    'A lava flow is a stream of molten rock that runs down the flank after magma reaches the surface.',
    fc, { lava: true, extras: [tipGlow] });

  // ---------- Buttons ----------
  panel.on('cut', 'click', () => { cut = !cut; applyCut(); });
  panel.on('reset', 'click', () => {
    parts.forEach((p) => { p.position.copy(p.userData.home); p.quaternion.identity(); });
    selected = null;
    cut = true;
    applyCut();
    panel.set('name', { text: 'Stratovolcano' });
    panel.set('desc', { text: 'Tap any part to learn its role in the volcano.' });
  });
  applyCut();

  return {
    root,
    update(time) {
      parts.forEach((p, i) => {
        const sel = p === selected;
        p.userData.mats.forEach((m) => {
          if (sel) {
            m.emissive.copy(hl);
            m.emissiveIntensity = 0.45 + 0.2 * Math.sin(time * 4);
          } else {
            m.emissive.copy(m.userData.ec);
            m.emissiveIntensity = m.userData.ei * (p.userData.lava ? 1 + 0.15 * Math.sin(time * 2 + i) : 1);
          }
        });
      });
      smoke.rotation.y = time * 0.2;
      ventGlow.scale.setScalar(1 + 0.1 * Math.sin(time * 2.5));
      tipGlow.scale.setScalar(1 + 0.1 * Math.sin(time * 2 + 1));
      for (let i = 0; i < puffs.length; i++) {
        const p = puffs[i];
        const f = (time * 0.2 + i / puffs.length) % 1;
        p.position.set(p.userData.p0.x + Math.sin(time + i * 2) * 0.008 * f, p.userData.p0.y + f * 0.09, p.userData.p0.z);
        p.scale.setScalar(0.6 + f * 1.6);
      }
    },
  };
}
